import datetime as _dt
try:
    from zoneinfo import ZoneInfo as _Z;_dtoday=_dt.datetime.now(_Z('Europe/London')).date()
except Exception:_dtoday=_dt.date.today()
_up=lambda L:[r for r in L if _dt.date.fromisoformat(r[0])>=_dtoday]
_f=lambda s:_dt.date.fromisoformat(s).strftime('%a %-d %b %Y')
# 'Expected:' rows have no exact day at source: show the month, marked expected (here and in the alert/newsletter lists)
_fx=lambda a,t,F=_f:_dt.date.fromisoformat(a).strftime('%B %Y')+' (expected)' if t.startswith('Expected') else F(a)
_r=lambda L:''.join(f'<tr><td><b>{_fx(a,t)}</b></td><td>{e(c)}<br><span class="small">{e(n)}</span></td><td>{e(t)}</td><td><a href="{u}" rel="nofollow">source</a></td></tr>' for a,n,c,t,u in L)
# In-context alert box (same form/endpoint/signup.js as ALERT_TOP/WALERT). Reason to subscribe: the next 3 upcoming dates
# from this page's own sourced DL/AHEAD rows (NEXTD: today or later, Europe/London). The page covers several nations, so the
# visitor picks one (values nation:<id>, the same encoding PICK uses); cta 'deadlines'; id deadlines-alert (sitewide #get-alerts stays unique).
_dlr=DL+AHEAD;_dlk=[_dt.date.fromisoformat(r[0]).strftime('%-d %b %Y')+f': {i}' for i,r in enumerate(_dlr)]
_dln=[(lambda a,n,c,t,u:f'<b>{_fx(a,t,lambda x:_dt.date.fromisoformat(x).strftime("%-d %b %Y"))}, {e(n if c=="All of "+n else c)}:</b> {e(t)} (<a href="{e(u)}" rel="nofollow">source</a>)')(*_dlr[int(k.rsplit(": ",1)[1])]) for k in NEXTD(_dlk)]
_dlo=''.join(f'<option value="nation:{n["id"]}" data-name="{e(n["name"])}">{e(n["name"])}</option>' for n in d['nations'])
DLALERT=('<div class="alertbox alerttop" id="deadlines-alert"><h2>Get an email before these short-let deadlines</h2><p>We check every date on this page against its official source, and email you when a deadline in your nation moves or a new one is announced.</p>'
 +((f'<p class="anxh"><b>Next deadlines we\'re watching:</b></p><ul class="anx">'+''.join(f'<li>{k}</li>' for k in _dln)+'</ul>') if _dln else '<p>We have no upcoming deadlines logged right now. If a council or government announces one, we\'ll email you.</p>')
 +'<p class="small">Plus one short weekly UK "what changed" email. Free, no spam, unsubscribe any time.</p>'
 +FORMX.replace('<form class="signup"','<form class="signup pick" data-cta="deadlines" aria-label="Get an email before these short-let deadlines"',1).replace('<input type="email"','<label class="sr" for="deadlines-alert-area">Your nation</label><select name="area" id="deadlines-alert-area" required><option value="">Choose your nation</option>'+_dlo+'</select><input type="email"',1).replace('>Subscribe<','>Get free alerts<')+'</div>')
# Common questions (visible + FAQPage JSON-LD). Built inline (guides.py shadows FAQ() with a list). Sources re-checked 31 Oct 2026:
# gov.wales WRA "Registering visitor accommodation: overview" (updated 29 Oct 2026) and "Check if your local council charges Visitor Levy";
# "Licensing of visitor accommodation in Wales" (8 May 2026); legislation.gov.uk asc/2026/10 s.61; City of Edinburgh Council visitor levy
# guidance v2.1 (Sept 2026) submission/payment table; VisitScotland.org visitor levy page (Glasgow, Aberdeen, Stirling, West Dunbartonshire);
# GOV.UK self-catering holiday homes in England (updated 2 Oct 2026); GOV.UK Self Assessment deadlines; gov.scot STL guidance Part 1 s.6, Part 2 s.2.
DLQ=[('When do I need to register my holiday let in Wales?','If your accommodation is open for bookings before 1 April 2027, you must register with the Welsh Revenue Authority (WRA) by 31 March 2027. This applies if you take bookings for overnight stays in Wales of 31 nights or fewer, even if your council never charges a visitor levy. Registration is free. If you start taking bookings after 1 April 2027, register before you open for bookings.'),
 ('When does the visitor levy start in Cardiff?','Cardiff Council starts the visitor levy on 1 April 2027, and Cardiff providers must start accounting for it from 28 September 2026. Cardiff is the only Welsh council charging the levy so far, and the WRA lists no councils consulting on one.'),
 ('When are Edinburgh visitor levy returns and payments due?','Returns are quarterly, in arrears, through visitorlevy.scot. For stays from 1 October to 31 December 2026, submit your return between 1 and 30 January 2027 and pay by 13 February 2027. For stays from 1 January to 31 March 2027, submit between 1 and 30 April 2027 and pay by 14 May 2027. If a stay spans two quarters, include it in the return for the quarter when the guest checked out.'),
 ('When do the other Scottish visitor levies start?','Glasgow: 5% for the full stay, from 25 January 2027. Aberdeen: 7% for the full stay, from 1 April 2027, on bookings made from 1 October 2026. Stirling: 3%, from 14 June 2027, on bookings made from 1 January 2027 (Stirling residents are exempt, and nights beyond 7 can be refunded). West Dunbartonshire: 5% for the full stay, from 1 July 2027, on bookings made from 1 October 2026.'),
 ('When does short-term let registration start in England?','GOV.UK (updated 2 October 2026) says the mandatory national registration scheme for short-term lets in England is expected to begin in March 2027. No exact date, regulations, portal or fee have been published yet, so there is nothing to register with today.'),
 ('When should I renew my short-term let licence in Scotland?','Before it expires. You can apply to renew at any time before expiry, and if your licence expires while the council is still deciding, you can keep letting until it decides. If your licence lapses before you apply, you must make a new application instead. Councils usually grant licences for up to 3 years at first, so check the expiry date on your licence and your council\'s advice on how early to apply.'),
 ('When is the Self Assessment deadline for holiday let income?','For the 2025 to 2026 tax year, paper returns must reach HMRC by 11:59pm on 31 October 2026 and online returns are due by 11:59pm on 31 January 2027. Any tax you owe must also be paid by 11:59pm on 31 January 2027. To pay through your tax code instead, file online by 30 December 2026.'),
 ('When will holiday lets in Wales need a licence?','Not yet. Licensing is a separate scheme under the Development of Tourism and Regulation of Visitor Accommodation (Wales) Act 2026, starting with self-catering accommodation. The Welsh Government says the legal default is that the scheme comes into force in March 2030 (section 61 of the Act), and there will be more consultation on the detailed rules first. WRA registration is the step you need to take now.'),
 ('How do you keep these dates up to date?','The UK Short-Let Rules team checks every date on this page against its official source, linked in each row. Dates that have passed drop off automatically, and changes are logged in our changes log. Dates can still move, so always check the source before acting.')]
DLQLD=json.dumps({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in DLQ]}).replace('</','<\\/')
DLQH=('<h2 id="deadlines-faq">Common questions</h2><div class="faq">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in DLQ)+'</div>'
 +'<p class="small">More detail: <a href="wales-registration-checker">Wales registration checker</a> · <a href="levy-calculator">Visitor levy calculator</a> · <a href="uk-visitor-levy-map">UK visitor levy map</a> · <a href="england-short-term-let-rules-2027">England registration in 2027</a> · <a href="scotland-licence-renewal-checker">Scotland licence renewal checker</a> · <a href="holiday-let-tax-after-fhl-abolition">Holiday let tax</a> · <a href="wales-visitor-accommodation-licensing">Wales licensing</a> · <a href="changes">Changes log</a>.</p>'
 +'<p class="small">Sources: <a href="https://www.gov.wales/registering-visitor-accommodation-overview" rel="nofollow">WRA: registering visitor accommodation</a>, <a href="https://www.gov.wales/check-if-local-council-charges-visitor-levy-wales" rel="nofollow">WRA: councils charging the levy</a>, <a href="https://www.gov.wales/licensing-visitor-accommodation-wales" rel="nofollow">Welsh Government: licensing</a>, <a href="https://www.legislation.gov.uk/asc/2026/10/section/61" rel="nofollow">2026 Act, section 61</a>, <a href="https://www.edinburgh.gov.uk/visitorlevyinformation" rel="nofollow">City of Edinburgh Council visitor levy guidance</a>, <a href="https://www.visitscotland.org/tourism-events-industry/visitor-levy" rel="nofollow">VisitScotland: visitor levy schemes</a>, <a href="https://www.gov.uk/guidance/letting-out-a-self-catering-holiday-home-in-england-rules-and-regulations" rel="nofollow">GOV.UK: self-catering holiday homes in England</a>, <a href="https://www.gov.uk/self-assessment-tax-returns/deadlines" rel="nofollow">GOV.UK: Self Assessment deadlines</a>, <a href="https://www.gov.scot/publications/short-term-lets-licensing-scheme-part-1-guidance-hosts-operators/pages/6/" rel="nofollow">Scottish Government: renewals</a>, <a href="https://www.gov.scot/publications/short-term-lets-licensing-scheme-part-2-supplementary-guidance-licensing-authorities-letting-agencies-booking-platforms/pages/2/" rel="nofollow">Scottish Government: licence duration</a>. Checked 31 Oct 2026.</p>')
_cu=_up(DL);_cr=(_dt.date.fromisoformat(_cu[0][0]).strftime('%-d %b %Y')+' to '+_dt.date.fromisoformat(_cu[-1][0]).strftime('%-d %b %Y')) if _cu else 'none upcoming'
page('deadlines.html','UK short-let deadlines: next 90 days',f'''<p class="lead">Every UK short-term let and holiday let date we track for the next 90 days, then the bigger dates to July 2027: levy start dates, levy returns and payments, Self Assessment and Making Tax Digital deadlines, council tax premiums, consultations closing and council decisions, in all four nations. Each date re-checked against its official source on 28 Oct 2026; past dates drop off automatically.</p>
<p><img src="deadlines-nov.png" alt="Card listing UK short-let deadlines from {_cr}" width="540" height="675" style="max-width:100%;height:auto;border-radius:12px;box-shadow:0 2px 10px rgba(0,0,0,.12)"></p>
<p><a href="deadlines-nov.png" download>Download the card (PNG)</a> to share. Please link back to this page.</p>
<div class="tw"><table><tr><th>Date</th><th>Where</th><th>What</th><th>Official source</th></tr>{_r(_up(DL))}</table></div>
<h2>Looking further ahead</h2><div class="tw"><table><tr><th>Date</th><th>Where</th><th>What</th><th>Official source</th></tr>{_r(_up(AHEAD))}</table></div>
<p>Dates can move. Check the source before acting, and see the <a href="changes.html">changes log</a> for updates.</p>
{DLALERT}
{DLQH}''',desc='UK short-let deadlines: Self Assessment, Edinburgh and Glasgow levy dates, consultations closing, then Aberdeen, Cardiff and Stirling levies, England register and premiums to July 2027. Official sources.',full_title='UK short-let deadlines: next 90 days and 2027 dates | UK Short-Let Rules',head='<script type="application/ld+json">'+DLQLD+'</script>')
# card HTML for the PNG (outside the site)
_card=''.join(f'<div class="r"><div class="d">{_dt.date.fromisoformat(a).strftime("%-d %b")}</div><div><b>{e(c)}</b> {e(t)}</div></div>' for a,n,c,t,u in _up(DL))
